CREATE TABLE project_policies(projectId TEXT PRIMARY KEY REFERENCES projects(id), liveEnabled INTEGER NOT NULL DEFAULT 0 CHECK(liveEnabled IN (0,1)), maxTurns INTEGER NOT NULL DEFAULT 3 CHECK(maxTurns BETWEEN 1 AND 20), timeoutMs INTEGER NOT NULL DEFAULT 120000 CHECK(timeoutMs BETWEEN 1000 AND 600000), maxMessages INTEGER NOT NULL DEFAULT 100 CHECK(maxMessages BETWEEN 1 AND 1000), version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE agent_sessions(id TEXT PRIMARY KEY, projectId TEXT NOT NULL REFERENCES projects(id), agentId TEXT NOT NULL REFERENCES agents(id), provider TEXT NOT NULL, providerSessionId TEXT, workspaceId TEXT, state TEXT NOT NULL, createdAt INTEGER NOT NULL, endedAt INTEGER);
ALTER TABLE runs ADD COLUMN sessionId TEXT REFERENCES agent_sessions(id);
ALTER TABLE runs ADD COLUMN workspaceId TEXT;
ALTER TABLE runs ADD COLUMN providerTurnId TEXT;
ALTER TABLE runs ADD COLUMN timeoutMs INTEGER NOT NULL DEFAULT 120000;
ALTER TABLE runs ADD COLUMN maxTurns INTEGER NOT NULL DEFAULT 3;
ALTER TABLE runs ADD COLUMN resumeSessionId TEXT;
ALTER TABLE runs ADD COLUMN transport TEXT NOT NULL DEFAULT 'structured';
ALTER TABLE machines ADD COLUMN providers TEXT NOT NULL DEFAULT '["demo"]' CHECK(json_valid(providers));
ALTER TABLE approval_decisions ADD COLUMN sessionId TEXT REFERENCES agent_sessions(id);
ALTER TABLE approval_decisions ADD COLUMN toolId TEXT;
ALTER TABLE approval_decisions ADD COLUMN kind TEXT NOT NULL DEFAULT 'tool';
ALTER TABLE approval_decisions ADD COLUMN decisionSentAt INTEGER;
ALTER TABLE approval_decisions ADD COLUMN state TEXT NOT NULL DEFAULT 'pending';
CREATE UNIQUE INDEX approval_request_identity ON approval_decisions(runId,providerRequestId);
CREATE TABLE tool_invocations(id TEXT PRIMARY KEY, projectId TEXT NOT NULL REFERENCES projects(id), runId TEXT NOT NULL REFERENCES runs(id), sessionId TEXT NOT NULL REFERENCES agent_sessions(id), providerToolId TEXT NOT NULL, providerTurnId TEXT, parentToolId TEXT, name TEXT NOT NULL, state TEXT NOT NULL, summary TEXT NOT NULL, startedAt INTEGER NOT NULL, endedAt INTEGER, UNIQUE(runId,providerToolId));
CREATE TABLE usage_totals(runId TEXT NOT NULL REFERENCES runs(id), turnId TEXT NOT NULL, inputTokens INTEGER NOT NULL DEFAULT 0, outputTokens INTEGER NOT NULL DEFAULT 0, source TEXT NOT NULL, estimated INTEGER NOT NULL DEFAULT 0, currency TEXT, costMicros INTEGER, pricingDate TEXT, PRIMARY KEY(runId,turnId));
CREATE TABLE workspaces(id TEXT PRIMARY KEY, projectId TEXT NOT NULL REFERENCES projects(id), workId TEXT NOT NULL REFERENCES work_items(id), machineId TEXT NOT NULL REFERENCES machines(id), repository TEXT NOT NULL, path TEXT NOT NULL, branch TEXT NOT NULL, baseSha TEXT NOT NULL, headSha TEXT NOT NULL, state TEXT NOT NULL, createdAt INTEGER NOT NULL);
CREATE TABLE artifacts(id TEXT PRIMARY KEY, projectId TEXT NOT NULL REFERENCES projects(id), workId TEXT REFERENCES work_items(id), runId TEXT REFERENCES runs(id), name TEXT NOT NULL, mime TEXT NOT NULL, sha256 TEXT NOT NULL, bytes INTEGER NOT NULL, body TEXT, createdAt INTEGER NOT NULL);
CREATE TABLE verification_evidence(id TEXT PRIMARY KEY, projectId TEXT NOT NULL REFERENCES projects(id), workId TEXT NOT NULL REFERENCES work_items(id), workspaceId TEXT NOT NULL REFERENCES workspaces(id), harnessHash TEXT NOT NULL, headBefore TEXT NOT NULL, headAfter TEXT NOT NULL, baseBefore TEXT NOT NULL, baseAfter TEXT NOT NULL, status TEXT NOT NULL, logHash TEXT NOT NULL, exitCode INTEGER, details TEXT NOT NULL CHECK(json_valid(details)), createdAt INTEGER NOT NULL);
CREATE TABLE reservations(id TEXT PRIMARY KEY, projectId TEXT NOT NULL REFERENCES projects(id), agentId TEXT NOT NULL REFERENCES agents(id), path TEXT NOT NULL, expiresAt INTEGER NOT NULL, epoch INTEGER NOT NULL, releasedAt INTEGER);
CREATE INDEX reservation_conflicts ON reservations(projectId,path,expiresAt);
CREATE TABLE outbox_deliveries(outboxId TEXT PRIMARY KEY REFERENCES outbox(id), handledAt INTEGER NOT NULL);
